def find_components(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    def flood(start_r, start_c, val):
        comp = [(start_r, start_c)]
        queue = __import__('collections').deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr, nc) not in visited and grid[nr][nc] == val:
                        visited.add((nr, nc))
                        comp.append((nr, nc))
                        queue.append((nr, nc))
        return comp

    vals = set()
    for row in grid:
        for v in row:
            vals.add(v)

    for v in sorted(vals):
        for r in range(h):
            for c in range(w):
                if grid[r][c] == v and (r,c) not in visited:
                    comps = flood(r, c, v)
                    if comps:
                        components.append(comps)
    return components

comps = find_components(grid)
print(f"Found {len(comps)} connected components")

by_size = sorted(comps, key=len, reverse=True)
for i, c in enumerate(by_size):
